SELECT ROW_NUMBER() OVER ( ORDER BY
ev_date ev_cd dv_name dv_addr ev_car_num ev_date
ASC DESC
, ev_id DESC ) AS rn , A.ev_date , A.ev_dv_name , A.ev_dv_addr , A.ev_car_num , A.ev_cd , A.ev_serial_number , A.ev_dv_ip , B.dv_id , B.dv_addr , B.dv_name FROM tbl_event_data A LEFT JOIN tbl_device B ON A.ev_dv_id = B.dv_id
where 1=1
AND ( A.ev_car_num like CONCAT('%',#{searchKeyword},'%') OR B.dv_addr like CONCAT('%',#{searchKeyword},'%') OR B.dv_name like CONCAT('%',#{searchKeyword},'%'))
AND LEFT(A.ev_date, 8) BETWEEN #{startDate} AND #{endDate}
AND A.ev_cd = #{evCd}
AND A.ev_action = #{evAction}
LIMIT #{recordCountPerPage}
OFFSET #{firstIndex}

SELECT COUNT(*) 
FROM tbl_event_data A
LEFT JOIN tbl_device B
ON A.ev_dv_id = B.dv_id


		AND ( A.ev_car_num like CONCAT('%',#{searchKeyword},'%')
		OR B.dv_addr like CONCAT('%',#{searchKeyword},'%')
		OR B.dv_name like CONCAT('%',#{searchKeyword},'%'))



		AND LEFT(A.ev_date, 8) BETWEEN #{startDate} AND #{endDate}


		AND A.ev_cd = #{evCd}


		AND A.ev_action = #{evAction}

